/*
 * Executable check for the target-version adaptation of CVE-2019-15221 fix.
 *
 * Reference guard (target v5.2 refactor code):
 *     if (!max_packet_size_in || !max_packet_size_out) -> reject
 * Target guard (v4.4 combined field):
 *     max_packet_size = min(max_packet_size_in, max_packet_size_out);
 *     if (!max_packet_size) -> reject
 *
 * This program proves the two predicates are equivalent over the whole
 * unsigned domain relevant to usb_maxpacket() return values, and that the
 * positive path keeps proceeding.
 */
#include <stdio.h>
#include <stdlib.h>

static int reject_reference(unsigned in, unsigned out)
{
	return (!in || !out);
}

static unsigned target_combined(unsigned in, unsigned out)
{
	return in < out ? in : out; /* min() */
}

static int reject_target(unsigned in, unsigned out)
{
	return (!target_combined(in, out));
}

int main(void)
{
	unsigned vals[] = { 0u, 1u, 2u, 8u, 16u, 64u, 512u, 1023u, 1024u, 65535u };
	size_t i, j, n = sizeof(vals) / sizeof(vals[0]);
	unsigned long checked = 0;
	int mismatches = 0;

	for (i = 0; i < n; i++) {
		for (j = 0; j < n; j++) {
			int a = reject_reference(vals[i], vals[j]);
			int b = reject_target(vals[i], vals[j]);
			checked++;
			if (a != b) {
				printf("MISMATCH in=%u out=%u ref=%d target=%d\n",
				       vals[i], vals[j], a, b);
				mismatches++;
			}
			/* negative path: either endpoint zero -> reject */
			if ((vals[i] == 0 || vals[j] == 0) && b != 1) {
				printf("NEGATIVE PATH FAIL in=%u out=%u\n", vals[i], vals[j]);
				mismatches++;
			}
			/* positive path: both nonzero -> accept (guard not taken) */
			if (vals[i] != 0 && vals[j] != 0 && b != 0) {
				printf("POSITIVE PATH FAIL in=%u out=%u\n", vals[i], vals[j]);
				mismatches++;
			}
		}
	}
	printf("checked=%lu mismatches=%d\n", checked, mismatches);
	return mismatches == 0 ? 0 : 1;
}

